use moloch_replay::session::{Session,atomic_json,propose_live_engine_upgrade};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::{fs,path::PathBuf,time::{SystemTime,UNIX_EPOCH}};
fn seal(mut v:Value)->Value{v.as_object_mut().unwrap().remove("hash");v["hash"]=json!(format!("{:x}",Sha256::digest(serde_json::to_vec(&v).unwrap())));v}
fn read(path:&std::path::Path)->Value{serde_json::from_slice(&fs::read(path).unwrap()).unwrap()}
struct Temp(PathBuf);impl Temp{fn new()->Self{let p=std::env::temp_dir().join(format!("moloch-upgrade-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&p).unwrap();Self(p)}}impl Drop for Temp{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn seed()->Value{json!({"runId":"upgrade-fixture","accountSnapshotHash":"b".repeat(64),"availableCash":"1000.000000","observedAt":"2026-10-15T00:00:00Z"})}
fn tick(at:&str)->Value{json!({"type":"tick","receivedAt":at})}
fn old_fixture(root:&std::path::Path,events:bool){let mut bank=Session::open_live(root,&json!({}),&seed()).unwrap();if events{bank.accept("clock",1,&tick("2026-10-15T00:00:00Z")).unwrap();}drop(bank);let mut manifest=read(&root.join("manifest.json"));manifest["engineIdentity"]=json!("a".repeat(64));let manifest=seal(manifest);atomic_json(&root.join("manifest.json"),&manifest).unwrap();for name in ["head.json","report.json"]{let mut v=read(&root.join(name));v["manifestHash"]=manifest["hash"].clone();atomic_json(&root.join(name),&seal(v)).unwrap();}}
fn approve(root:&std::path::Path)->Value{let proof=propose_live_engine_upgrade(root,&"c".repeat(64),"2026-10-15T00:00:01Z").unwrap();atomic_json(&root.join("engine-upgrade-v1.json"),&proof).unwrap();proof}
#[test]fn exact_upgrade_keeps_manifest_and_prefix_then_accepts_appended_suffix_on_restart(){let t=Temp::new();let root=t.0.join("bank");old_fixture(&root,true);let manifest=fs::read(root.join("manifest.json")).unwrap();let prefix=fs::read(root.join("events.jsonl")).unwrap();assert!(Session::open_live(&root,&json!({}),&seed()).is_err());approve(&root);let expected;{let mut bank=Session::open_live(&root,&json!({}),&seed()).unwrap();bank.accept("clock",2,&tick("2026-10-15T00:00:02Z")).unwrap();expected=bank.engine().report().unwrap();}let bank=Session::open_live(&root,&json!({}),&seed()).unwrap();assert_eq!(bank.engine().report().unwrap(),expected);assert_eq!(fs::read(root.join("manifest.json")).unwrap(),manifest);assert!(fs::read(root.join("events.jsonl")).unwrap().starts_with(&prefix));}
#[test]fn zero_event_prefix_is_a_valid_exact_upgrade_boundary(){let t=Temp::new();let root=t.0.join("bank");old_fixture(&root,false);approve(&root);assert!(Session::open_live(&root,&json!({}),&seed()).is_ok());}
#[test]fn validly_resealed_wrong_prefix_report_identity_or_approval_does_not_bypass_checks(){for case in ["bytes","hash","report","identity","approval"]{let t=Temp::new();let root=t.0.join("bank");old_fixture(&root,true);let mut proof=approve(&root);let entry=&mut proof["upgrades"][0];match case{"bytes"=>entry["journalPrefix"]["bytes"]=json!(1),"hash"=>entry["journalPrefix"]["sha256"]=json!("d".repeat(64)),"report"=>{let mut report=entry["oldReportEnvelope"].clone();report["report"]["cash"]=json!("999.000000");entry["oldReportEnvelope"]=seal(report);},"identity"=>entry["toEngineIdentity"]=json!("e".repeat(64)),_=>entry["approval"]["previousProcessStopped"]=json!(false)}*entry=seal(entry.clone());proof=seal(proof);atomic_json(&root.join("engine-upgrade-v1.json"),&proof).unwrap();assert!(Session::open_live(&root,&json!({}),&seed()).is_err(),"{case}");}}
#[test]fn proof_creation_requires_a_released_writer_and_existing_committed_head(){let t=Temp::new();let root=t.0.join("bank");let bank=Session::open_live(&root,&json!({}),&seed()).unwrap();assert!(propose_live_engine_upgrade(&root,&"c".repeat(64),"2026-10-15T00:00:01Z").is_err());drop(bank);old_fixture_existing(&root);let mut head=read(&root.join("head.json"));head["sequence"]=json!(5);atomic_json(&root.join("head.json"),&seal(head)).unwrap();assert!(propose_live_engine_upgrade(&root,&"c".repeat(64),"2026-10-15T00:00:01Z").is_err());}
fn old_fixture_existing(root:&std::path::Path){let mut manifest=read(&root.join("manifest.json"));manifest["engineIdentity"]=json!("a".repeat(64));let manifest=seal(manifest);atomic_json(&root.join("manifest.json"),&manifest).unwrap();for name in ["head.json","report.json"]{let mut v=read(&root.join(name));v["manifestHash"]=manifest["hash"].clone();atomic_json(&root.join(name),&seal(v)).unwrap();}}

#[test]fn identity_bridge_reproduces_real_order_binding_and_partial_fill_history(){
 let t=Temp::new();let root=t.0.join("bank");let expected;let bindings;
 {let mut bank=Session::open_live(&root,&json!({}),&seed()).unwrap();let at="2026-10-15T00:00:00Z";bank.accept("market",1,&json!({"type":"book","receivedAt":at,"book":{"tournamentId":"cup","marketId":"211","exchangeId":"900","requestStartedAt":at,"receivedAt":at,"sourceAt":at,"sequence":"1","bids":[{"price":"0.200000","quantity":100}],"asks":[{"price":"0.300000","quantity":100}]}})).unwrap();let q=bank.engine().order_records().into_iter().find(|q|q["side"]=="NO").unwrap();let mut ack=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":q["id"],"actualOrderId":"201","exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":"2026-10-15T00:00:01Z"});bank.accept("account",1,&ack).unwrap();ack["type"]=json!("actual_fill");ack["fillId"]=json!("301");ack["quantity"]=json!(1);ack["price"]=json!("0.700000");ack["fee"]=json!("0.000000");ack["executedAt"]=json!("2026-10-15T00:00:03Z");ack["receivedAt"]=json!("2026-10-15T00:00:04Z");bank.accept("account",2,&ack).unwrap();expected=bank.engine().report().unwrap();bindings=bank.engine().live_order_bindings().clone();}
 old_fixture_existing(&root);approve(&root);let bank=Session::open_live(&root,&json!({}),&seed()).unwrap();assert_eq!(bank.engine().report().unwrap(),expected);assert_eq!(bank.engine().live_order_bindings(),&bindings);assert_eq!(bank.engine().fills().len(),1);
}

#[test]fn approved_prefix_survives_durable_adoption_and_effective_policy_suffix(){
 let t=Temp::new();let root=t.0.join("bank");old_fixture(&root,true);let original_manifest=fs::read(root.join("manifest.json")).unwrap();approve(&root);let event=json!({"type":"actual_position_adoption","source":"official_sig_api_v1","authority":"human_moloch_inherited_management_20261015","complete":true,"tournamentId":"cup","receiptHash":"f".repeat(64),"requestStartedAt":"2026-10-15T00:00:01Z","receivedAt":"2026-10-15T00:00:01.001Z","processedAt":"2026-10-15T00:00:02Z","openingCost":"3.450000","effectiveMaximumMarkets":5,"positions":[{"exchangeId":"900","marketId":"211","quantity":-5,"lotPrincipal":"3.450000","reportedCostBasis":"3.450000","reportedMinusLotPrincipal":"0.000000","basisClassification":"exact","lots":[{"lotId":"701","quantity":5,"side":"NO","entryPrice":"0.690000","openedAt":"2026-10-09T02:00:00.1234567+00:00"}]}]});let expected;
 {let mut bank=Session::open_live(&root,&json!({}),&seed()).unwrap();assert!(bank.accept("inherited",1,&event).unwrap());expected=bank.engine().report().unwrap();assert_eq!(bank.engine().policy()["maximumMarkets"],5);assert_eq!(expected["fills"],0);}
 let mut bank=Session::open_live(&root,&json!({}),&seed()).unwrap();assert_eq!(bank.engine().report().unwrap(),expected);assert!(!bank.accept("inherited",1,&event).unwrap());assert_eq!(fs::read(root.join("manifest.json")).unwrap(),original_manifest);assert_eq!(bank.engine().opening_inventory_cost(),3_450_000);
}


#[test]fn original_sealed_upgrade_above_eight_mib_replays_without_mutating_history(){
 let t=Temp::new();let root=t.0.join("large-bank");old_fixture(&root,true);
 let manifest=fs::read(root.join("manifest.json")).unwrap();let journal=fs::read(root.join("events.jsonl")).unwrap();let original_report=read(&root.join("report.json"));
 let mut proof=approve(&root);proof["retainedAuditPadding"]=json!("x".repeat(8*1024*1024));proof=seal(proof);atomic_json(&root.join("engine-upgrade-v1.json"),&proof).unwrap();
 let proof_bytes=fs::read(root.join("engine-upgrade-v1.json")).unwrap();assert!(proof_bytes.len()>8*1024*1024&&proof_bytes.len()<32*1024*1024);
 let bank=Session::open_live(&root,&json!({}),&seed()).unwrap();assert_eq!(bank.engine().report().unwrap(),original_report["report"]);drop(bank);
 assert_eq!(fs::read(root.join("manifest.json")).unwrap(),manifest);assert_eq!(fs::read(root.join("events.jsonl")).unwrap(),journal);assert_eq!(fs::read(root.join("engine-upgrade-v1.json")).unwrap(),proof_bytes);
 proof["retainedAuditPadding"]=json!("y".repeat(8*1024*1024));atomic_json(&root.join("engine-upgrade-v1.json"),&proof).unwrap();assert_eq!(Session::open_live(&root,&json!({}),&seed()).err().unwrap().to_string(),"UPGRADE_HASH_MISMATCH");
}
#[test]fn upgrade_document_above_thirty_two_mib_is_rejected_before_parsing(){
 let t=Temp::new();let root=t.0.join("oversized-bank");old_fixture(&root,true);approve(&root);let manifest=fs::read(root.join("manifest.json")).unwrap();let head=fs::read(root.join("head.json")).unwrap();
 fs::File::create(root.join("engine-upgrade-v1.json")).unwrap().set_len(32*1024*1024+1).unwrap();assert_eq!(Session::open_live(&root,&json!({}),&seed()).err().unwrap().to_string(),"UPGRADE_FILE_BOUND");assert_eq!(fs::read(root.join("manifest.json")).unwrap(),manifest);assert_eq!(fs::read(root.join("head.json")).unwrap(),head);
}
#[cfg(unix)]#[test]fn upgrade_document_symlink_is_rejected_even_with_valid_sealed_target(){
 let t=Temp::new();let root=t.0.join("linked-bank");old_fixture(&root,true);approve(&root);let original=fs::read(root.join("engine-upgrade-v1.json")).unwrap();let target=t.0.join("retained-proof.json");fs::rename(root.join("engine-upgrade-v1.json"),&target).unwrap();std::os::unix::fs::symlink(&target,root.join("engine-upgrade-v1.json")).unwrap();
 assert_eq!(Session::open_live(&root,&json!({}),&seed()).err().unwrap().to_string(),"UPGRADE_FILE_BOUND");assert_eq!(fs::read(target).unwrap(),original);
}
#[test]fn larger_byte_bound_does_not_relax_sixteen_entry_chain_cap(){
 let t=Temp::new();let root=t.0.join("too-many-upgrades");old_fixture(&root,true);let mut proof=approve(&root);let original=proof["upgrades"][0].clone();proof["upgrades"]=json!(vec![original;17]);proof=seal(proof);atomic_json(&root.join("engine-upgrade-v1.json"),&proof).unwrap();assert_eq!(Session::open_live(&root,&json!({}),&seed()).err().unwrap().to_string(),"UPGRADE_CHAIN_BOUND");
}
